def wrap(text, width):
    if width < 1:
        raise ValueError("width must be >= 1")
    words = text.split()
    # split long words
    pieces = []
    for w in words:
        while len(w) > width:
            pieces.append(w[:width])
            w = w[width:]
        if w:
            pieces.append(w)
    lines = []
    cur = ""
    for p in pieces:
        if not cur:
            cur = p
        elif len(cur) + 1 + len(p) <= width:
            cur += " " + p
        else:
            lines.append(cur)
            cur = p
    if cur:
        lines.append(cur)
    return lines

